suppressPackageStartupMessages({library(data.table);library(ggplot2);library(patchwork)})
root<-Sys.getenv('MASLD_PROJECT_ROOT');out<-Sys.getenv('S4DE_RENDER_ROOT');stopifnot(nzchar(root),nzchar(out),!dir.exists(out));dir.create(out,recursive=TRUE)
source(file.path(root,'scripts/figures/publication_theme.R'));grDevices::pdf.options(useDingbats=FALSE)
input<-file.path(root,'Analysis/SingleCell/candidates/source-qualified-CCC-20261014_22237840')
fixed<-fread(file.path(input,'fixed_13_current_stage_context.tsv'));bridge<-fread(file.path(input,'fig4d_program_ccc_associations.tsv'));matched<-fread(file.path(input,'fig4d_program_ccc_matched_donors.tsv'))
qual<-fread(file.path(root,'Analysis/SingleCell/candidates/source-diagnosis-primary-correction-20261014/metadata/current_source_diagnosis_donor_roster.tsv'));qual[,exclude:=tolower(as.character(exclude))=='true']
lr<-fread(file.path(root,'Analysis/SingleCell/results_gpu_v2_phase05/ccc/stage_trajectory_v2/all_donor_lr_scores_v2_dc.tsv.gz'));lr<-merge(lr,qual[,.(sample=donor,disease_stage_coarse,exclude)],by='sample',all.x=TRUE)
stopifnot(all(lr[is.na(exclude)]$dataset=='Liver_Atlas'));lr[is.na(exclude),exclude:=TRUE]
lr<-lr[!exclude&disease_stage_coarse%in%c('Healthy','Steatosis','Steatohepatitis')]
lr[,`:=`(score=-log10(pmax(magnitude_rank,1e-4)),ct_pair=paste(source,target,sep='->'),lr_pair=paste(ligand_complex,receptor_complex,sep='__'))]
lr<-merge(lr,fixed[,.(ct_pair,lr_pair,headline_label,dc_q,disposition)],by=c('ct_pair','lr_pair'));stopifnot(!anyDuplicated(lr[,.(sample,ct_pair,lr_pair)]))
ccc<-lr[,.(mean_score=mean(score),se=sd(score)/sqrt(.N),n=.N),by=.(ct_pair,lr_pair,headline_label,dc_q,disposition,disease_stage_coarse)]
ccc[,`:=`(donor_state=fifelse(disposition=='fitted','Testable; q=1','Untestable'),stage=factor(disease_stage_coarse,levels=c('Healthy','Steatosis','Steatohepatitis')))]
ccc[,row_z:=as.numeric(scale(mean_score)),by=headline_label];ccc[,lr_label:=gsub('  +',' ',gsub('_','/',headline_label))]
order_lr<-ccc[,.(delta=row_z[stage=='Steatohepatitis']-row_z[stage=='Healthy']),by=lr_label][order(-delta),lr_label];ccc[,lr_label:=factor(lr_label,levels=rev(order_lr))]
stopifnot(nrow(fixed)==13,sum(fixed$disposition=='fitted')==6,all(fixed[disposition=='fitted']$dc_q==1),nrow(ccc)==39)
pd<-ggplot(ccc,aes(stage,lr_label,fill=row_z,alpha=donor_state))+geom_tile(color='white',linewidth=.2)+scale_fill_gradient2(low=masld_colors$down,mid='white',high=masld_colors$mash,midpoint=0,limits=c(-1.5,1.5),oob=scales::squish,name='L-R z',breaks=c(-1.5,0,1.5),guide=guide_colorbar(barwidth=unit(18,'mm'),barheight=unit(2,'mm')))+scale_alpha_manual(values=c('Testable; q=1'=.45,'Untestable'=.22),guide='none')+labs(x=NULL,y=NULL,title='6 testable (q=1); 7 untestable')+theme_masld_compact()+theme(text=element_text(size=6,face='plain'),plot.title=element_text(size=6),plot.title.position='plot',legend.justification='left',axis.text.x=element_text(size=6,angle=25,hjust=1),axis.text.y=element_text(size=6),legend.position='bottom',legend.title=element_text(size=6),legend.text=element_text(size=6),legend.margin=margin(0,0,0,0))
key<-ggplot(data.frame(x=seq(-1.5,1.5,length.out=101),y=0),aes(x,y,fill=x))+geom_raster()+scale_fill_gradient2(low=masld_colors$down,mid='white',high=masld_colors$mash,midpoint=0,guide='none')+scale_x_continuous(breaks=c(-1.5,0,1.5),expand=expansion(mult=.04))+labs(x=NULL,y=NULL,title='L-R z')+theme_void(base_size=6)+theme(axis.text.x=element_text(size=6),plot.title=element_text(size=6,hjust=.5),plot.margin=margin(0,20,2,20))
pd_full<-wrap_plots(wrap_elements(full=pd+theme(legend.position='none')),wrap_elements(full=key),ncol=1,heights=c(1,.16))
ggsave(file.path(out,'figs4d_communication_heatmap.pdf'),pd_full,width=2.25,height=2.45,device=cairo_pdf)
# Native compact signed-coefficient screen and one positive partial-residual panel.
complex_expression<-function(value)paste(sprintf("italic('%s')",strsplit(value,'_',fixed=TRUE)[[1]]),collapse="*'/'*")
ct_short<-c(Hepatocytes='Hep',Fibroblasts='Fib',Macrophages='Mac',Cholangiocytes='Chol','Endothelial cells'='Endo')
bridge[,pair_plotmath:=mapply(function(ligand,receptor,send,receive)sprintf("%s*'→'*%s~'(%s→%s)'",complex_expression(ligand),complex_expression(receptor),ct_short[[send]],ct_short[[receive]]),ligand_complex,receptor_complex,sender,receiver)]
bridge[,supported_both:=testable&qvalue<.05&hc3_qvalue<.05]
ord<-bridge[,.(any_supported=any(supported_both),best_q=if(any(is.finite(qvalue)))min(qvalue,na.rm=TRUE)else Inf),by=.(ct_pair,lr_pair,pair_plotmath)];setorder(ord,-any_supported,best_q,ct_pair,lr_pair)
bridge[,`:=`(pair_plotmath=factor(pair_plotmath,levels=rev(ord$pair_plotmath)),program_short=factor(program_short,levels=c('ECM / IGFBP7','Ductular / BICC1')))]
display<-copy(bridge[testable==TRUE]);display[,pair_plotmath:=droplevels(pair_plotmath)];stopifnot(nrow(bridge)==26,nrow(display)==22,sum(bridge$supported_both)==2)
lim<-max(abs(bridge$beta),na.rm=TRUE)
ps<-ggplot(display,aes(program_short,pair_plotmath))+geom_point(aes(color=beta),shape=16,size=1.8)+geom_point(data=display[supported_both==TRUE],aes(color=beta),shape=16,size=2.8)+scale_color_gradient2(low=masld_colors$down,mid='#9E9E9E',high=masld_colors$mash,midpoint=0,limits=c(-lim,lim),oob=scales::squish,name=expression(beta),breaks=c(-lim,0,lim),labels=sprintf('%.2f',c(-lim,0,lim)),guide=guide_colorbar(barwidth=unit(20,'mm'),barheight=unit(2,'mm')))+scale_x_discrete(labels=expression('ECM / '*italic('IGFBP7'),'Ductular / '*italic('BICC1')),expand=expansion(add=c(1.25,1.25)))+scale_y_discrete(labels=function(x)parse(text=x))+labs(x=NULL,y=NULL,title='26 planned; 22 estimable; 2 supported')+theme_masld_compact()+theme(text=element_text(size=6,face='plain'),axis.text=element_text(size=6),axis.text.x=element_text(size=6,angle=22,hjust=1),legend.position='bottom',legend.title=element_text(size=6),legend.text=element_text(size=6),plot.title=element_text(size=6),plot.margin=margin(2,2,2,2))
hit<-bridge[supported_both&beta>0];stopifnot(nrow(hit)==1,hit$lr_pair=='CDH1__PTPRM',hit$n_donors==58)
d<-copy(matched[program_uid==hit$program_uid&ct_pair==hit$ct_pair&lr_pair==hit$lr_pair]);d[,`:=`(stage=factor(stage),dataset=factor(dataset),program_z=as.numeric(scale(program_score)))]
x<-lm(program_z~stage+dataset+log_source_cells+log_target_cells,data=d);y<-lm(ccc_score~stage+dataset+log_source_cells+log_target_cells,data=d);d[,`:=`(adjusted_program=residuals(x),adjusted_ccc=residuals(y))]
b<-coef(lm(adjusted_ccc~0+adjusted_program,data=d))[[1]];stopifnot(abs(b-hit$beta)<1e-10,nrow(d)==58)
stats<-sprintf('n=%d   β=%.2f\nBH[26] q=%.1e\nHC3 BH[26] q=%.1e',hit$n_donors,hit$beta,hit$qvalue,hit$hc3_qvalue)
ph<-ggplot(d,aes(adjusted_program,adjusted_ccc))+geom_hline(yintercept=0,color='grey88',linewidth=.3)+geom_vline(xintercept=0,color='grey88',linewidth=.3)+geom_point(shape=21,fill='#9E9E9E',color='white',stroke=.2,size=1.4,alpha=.78)+geom_smooth(method='lm',formula=y~0+x,se=TRUE,color=masld_colors$mash,fill=masld_colors$mash,alpha=.14,linewidth=.65)+annotate('text',x=-Inf,y=Inf,label=stats,hjust=-.04,vjust=1.08,size=6/ggplot2::.pt,family='Helvetica',lineheight=.95,color='#252525')+labs(x='Program (adjusted)',y='CCC (adjusted)',title=expression('Ductular score / '*italic('CDH1')*'→'*italic('PTPRM')))+theme_masld_compact()+theme(text=element_text(size=6,face='plain'),axis.title=element_text(size=6),axis.text=element_text(size=6),plot.title=element_text(size=6),plot.margin=margin(2,2,2,2))
ggsave(file.path(out,'figs4e_program_linked_communication.pdf'),ps|ph,width=5.15,height=2.45,device=cairo_pdf)
fwrite(ccc,file.path(out,'figs4d_communication_heatmap_source.tsv'),sep='\t');fwrite(bridge,file.path(out,'figs4e_program_linked_communication_source.tsv'),sep='\t');fwrite(d,file.path(out,'figs4e_supported_positive_partial_residuals.tsv'),sep='\t')
writeLines(capture.output(sessionInfo()),file.path(out,'sessionInfo.txt'));writeLines('S4D fixed13:6testable/allq1,7untestable. S4E fixed26:22estimable,2supported signed contextual associations; positiveCDH1partialresiduals n58 reproduce native adjusted beta. All font sizes6pt; candidate scientific state preserved.',file.path(out,'CHECKED.txt'))
